<?php
namespace App\Http\Controllers\Api\V1;

use App\Http\Requests\CurrencyAccountRequest; use App\Http\Requests\WalletCreationRequest; use App\Http\Requests\WalletPreferenceRequest; use App\Http\Resources\WalletCurrencyAccountResource; use App\Http\Resources\WalletResource; use App\Models\Currency; use App\Models\Wallet; use App\Services\WalletAccountService; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;

final class WalletController {
    public function index(Request $request): JsonResponse { $query=Wallet::with(['owner','currencyAccounts.currency','preferences.preferredCurrency'])->whereHas('owner',fn($q)=>$q->where('user_id',$request->user()->id)); if($request->filled('status'))$query->where('status',$request->string('status')); if($request->filled('search'))$query->where(fn($q)=>$q->where('nickname','ilike','%'.$request->string('search').'%')->orWhere('label','ilike','%'.$request->string('search').'%')); if($request->filled('currency'))$query->whereHas('currencyAccounts.currency',fn($q)=>$q->where('code',strtoupper($request->string('currency')))); $sort=in_array($request->string('sort')->toString(),['created_at','nickname','status'],true)?$request->string('sort')->toString():'created_at'; $wallets=$query->orderBy($sort,$request->string('direction')->toString()==='asc'?'asc':'desc')->paginate(min(max((int)$request->input('per_page',10),1),10)); return response()->json(['data'=>WalletResource::collection($wallets->items()),'meta'=>['current_page'=>$wallets->currentPage(),'last_page'=>$wallets->lastPage(),'per_page'=>$wallets->perPage(),'total'=>$wallets->total()],'demo_only'=>true]); }
    public function store(WalletCreationRequest $request,WalletAccountService $service): JsonResponse { $wallet=$service->create($request->user(),$request->string('currency_code')->toString(),$request->input('nickname')); return response()->json(['data'=>new WalletResource($wallet),'message'=>'Wallet account created. No financial capabilities are enabled.'],201); }
    public function show(Request $request,Wallet $wallet): JsonResponse { abort_unless(app(\App\Policies\WalletPolicy::class)->view($request->user(),$wallet->load('owner')),404,'Wallet not found.'); return response()->json(['data'=>new WalletResource($wallet->load(['owner','currencyAccounts.currency','preferences.preferredCurrency','statusHistory'])),'demo_only'=>true]); }
    public function updatePreferences(WalletPreferenceRequest $request,Wallet $wallet,WalletAccountService $service): JsonResponse { $service->assertOwner($request->user(),$wallet); $data=[]; if($request->filled('locale'))$data['locale']=$request->string('locale')->toString(); if($request->filled('preferred_currency_code')){$account=$wallet->currencyAccounts()->whereHas('currency',fn($q)=>$q->where('code',strtoupper($request->string('preferred_currency_code'))))->first(); abort_unless($account,422,'Preferred currency must be enabled on this wallet.'); $data['preferred_currency_id']=$account->currency_id;} $wallet->preferences()->updateOrCreate(['wallet_id'=>$wallet->id],$data); return response()->json(['data'=>new WalletResource($wallet->load(['owner','currencyAccounts.currency','preferences.preferredCurrency']))]); }
    public function currencies(Request $request,Wallet $wallet,WalletAccountService $service): JsonResponse { $service->assertOwner($request->user(),$wallet); return response()->json(['data'=>WalletCurrencyAccountResource::collection($wallet->currencyAccounts()->with('currency')->paginate(10)),'demo_only'=>true]); }
    public function addCurrency(CurrencyAccountRequest $request,Wallet $wallet,WalletAccountService $service): JsonResponse { $account=$service->addCurrency($request->user(),$wallet,$request->string('currency_code')->toString()); return response()->json(['data'=>new WalletCurrencyAccountResource($account),'message'=>'Currency account created. No balance is available until Phase 4.'],201); }
    public function currency(Request $request,Wallet $wallet,string $code,WalletAccountService $service): JsonResponse { $service->assertOwner($request->user(),$wallet); $account=$wallet->currencyAccounts()->with('currency')->whereHas('currency',fn($q)=>$q->where('code',strtoupper($code)))->first(); abort_unless($account,404,'Currency account not found.'); return response()->json(['data'=>new WalletCurrencyAccountResource($account),'demo_only'=>true]); }
    public function currenciesCatalog(): JsonResponse { return response()->json(['data'=>Currency::where('is_active',true)->orderBy('display_order')->get(['code','name','symbol','decimals','display_order','is_active']),'demo_only'=>true]); }
    public function overview(Request $request): JsonResponse { $wallets=Wallet::with('currencyAccounts.currency')->whereHas('owner',fn($q)=>$q->where('user_id',$request->user()->id))->get(); return response()->json(['data'=>['wallet_count'=>$wallets->count(),'wallets'=>WalletResource::collection($wallets),'estimated_balance'=>null,'estimated_balance_label'=>'Balances become authoritative after the Phase 4 ledger','recent_activity'=>[],'financial_actions_enabled'=>false],'demo_only'=>true]); }
}
